"""Explain instrumentation access classes, object sizes, markers and failed updates."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1589': ('기록원이 “읽기만 했는지, 쓰려고 했는지, 읽고 바꾸려 했는지”를 구분해 적는다고 생각해 봅시다. 모든 입력을 같은 종류로 기록하지는 않아요.', '인자 분류에 따라 생성되는 접근 보고의 종류를 이해합니다.', 'read의 cv → read, set의 v → write, add의 v → read_write, 값 i → 보고 없음의 표를 만드세요.', ['gen_param_check는 인자 명세를 읽어 접근 보고 hook을 만드는 쉘 함수예요. hook은 분석 기능을 연결해 부르는 지점이에요. 이 함수가 출력한 hook과 실제 원자 연산은 역할이 달라요.', '먼저 콜론 앞 타입과 뒤의 이름을 구별해요. i:new라면 타입은 i이고 이름은 new예요. 타입의 앞 c를 뺀 결과가 i이면 곧바로 돌아가서 접근 hook을 출력하지 않아요.', 'i는 전달된 정수값이에요. 여기서는 별도의 대상 위치를 가리키는 포인터가 아니므로 그 인자에 주소 접근 hook을 만들지 않아요. 이것이 C에서 값을 전달할 때 아무 기계적 작업도 없다는 뜻은 아니에요.', 'cv처럼 앞 c가 있는 포인터는 읽기 전용 분류예요. 이 경우 rw를 read로 골라 instrument_atomic_read를 출력해요. 포인터 자체와 그 포인터로 읽는 객체를 구별하세요.', '수정 가능한 포인터에서 meta가 s이면 단순 저장이라 write를 선택해요. 그 밖의 경우는 read_write를 선택해요. RMW는 읽고 계산해서 쓰는 연산이므로 이 분류로 보고해요.', '이 선택은 생성 시점의 명세를 보고 정해요. 실행 중 조건을 검사해서 저장에 성공했는지 알아낸 결과가 아니에요. 따라서 read_write 보고가 있었다고 반드시 실제 숫자가 바뀌었다고 판단하면 안 돼요.'], [('정수값을 뜻하는 i 인자에는 어떤 접근 hook을 생성하나요?', ['무조건 atomic_write를 만들어요', '이 도우미는 접근 hook을 만들지 않아요'], '정답은 두 번째예요. i를 만나면 출력 전에 돌아가요. 포인터로 전달된 대상 위치와 이미 전달된 정수값을 구별하는 규칙이에요.'), ('cv 인자의 접근 hook은 어떤 종류인가요?', ['instrument_atomic_read예요', 'instrument_atomic_write예요'], '정답은 첫 번째예요. 앞 c가 읽기 전용 포인터 분류임을 나타내므로 rw를 read로 골라요. 이를 쓰기 보고로 바꾸어 읽으면 안 돼요.')]), 'os1590': ('상자 주소가 적힌 쪽지의 크기와 그 주소의 상자 크기는 달라요. 접근을 보고할 때에는 쪽지가 아니라 실제로 다루는 상자의 크기를 알려 줘야 해요.', '포인터 크기와 가리키는 객체 크기, 접근 보고와 수명을 구별합니다.', 'v → 대상 객체를 그린 뒤 sizeof(v)는 위치값 자체의 크기, sizeof(*v)는 대상 객체의 크기라고 나눠 적으세요.', ['포인터는 자료의 위치를 가리키는 값이에요. v가 포인터라면 *v는 그 위치의 대상을 나타내는 C 표현이에요. sizeof는 해당 타입이나 대상의 크기를 바이트 단위로 구할 때 써요.', '생성된 hook은 v, sizeof(*v)처럼 주소와 크기를 함께 받아요. 주소는 어느 위치인지, 크기는 그 위치에서 어느 범위를 다루는지 분석 기능에 알려 주는 정보예요.', 'sizeof(v)는 포인터 값 자체의 크기이고 sizeof(*v)는 가리키는 객체의 크기예요. 둘이 어떤 환경에서 우연히 같더라도 뜻은 달라요. 예를 들어 포인터 8바이트, 대상 정수 4바이트인 환경에서는 보고할 대상 크기가 4바이트예요. 모든 환경의 크기가 이렇다는 뜻은 아니에요.', '같은 생성 규칙이라도 atomic_t·atomic64_t·atomic_long_t가 가리키는 타입에 따라 크기가 결정돼요. 생성기는 특정 숫자를 외워 넣는 대신 sizeof(*이름)이라는 C 표현을 출력해요.', '예상 값 메모를 가리키는 old 같은 추가 포인터가 있으면 그 위치도 별도로 보고해요. 실제 counter v와 예상 값 old는 서로 다른 저장 공간일 수 있으므로 주소와 대상 크기를 각각 봐야 해요.', '주소와 크기를 보고했다고 객체를 계속 살아 있게 유지하는 것은 아니에요. 자료가 아직 존재하는지와 사용 중에 사라지지 않는지는 호출자가 별도 규칙으로 보장해야 해요. sizeof도 이 고정 타입의 값을 실제로 읽어 유효한 주소인지 검사해 주는 기능이 아니에요.'], [('생성된 hook이 크기를 알릴 때 사용하는 표현은 무엇인가요?', ['항상 포인터 자체의 sizeof(v)예요', '가리키는 대상의 sizeof(*v)예요'], '정답은 두 번째예요. 분석 대상은 포인터 주소가 적힌 값 자체가 아니라 그 주소에서 접근하는 저장 공간이에요. 두 크기의 뜻을 구별하세요.'), ('주소와 크기를 보고하면 객체가 자동으로 살아 있게 유지되나요?', ['아니요. 자료의 수명을 지키는 규칙은 별도로 필요해요', '네. 보고만 하면 자동으로 참조가 추가돼요'], '정답은 첫 번째예요. 이 생성 코드는 접근 정보 보고를 만들어요. 자료를 계속 유지할 사용 권한이나 참조 수를 자동으로 얻는 코드가 아니에요.')]), 'os1591': ('기록원에게 “이 작업에는 이런 순서 약속이 있어요”라는 표시를 먼저 알려 줄 수 있어요. 분석용 표시와 CPU가 실제 순서를 지키는 구현을 나누어 봅시다.', '순서 이름과 분류에 따라 생성되는 KCSAN 표식을 이해합니다.', '기본 F → kcsan_mb → 접근 보고, _release → kcsan_release → 접근 보고, _acquire → 접근 보고의 세 줄을 적으세요.', ['gen_params_checks는 각 인자의 접근 hook 앞에 붙일 분석용 순서 표식을 골라요. KCSAN은 동시에 자료를 접근하는 문제를 살펴보는 커널 분석 기능이에요. 여기의 표식은 그 분석에 순서 정보를 전달하는 코드예요.', 'order가 _release이면 먼저 kcsan_release를 출력해요. 그다음 인자 목록을 돌며 접근 보고를 만들어요. release라는 이름을 실제 조건문에서 확인할 수 있어요.', 'order가 비어 있고 meta가 s·l·v 중 어느 것도 아니면 kcsan_mb를 출력해요. 주석은 반환값이 있는 RMW의 기본 full ordering과 연결해 설명해요. 기본 fetch_add의 F가 이 갈래에 해당해요.', '기본 읽기 l, 저장 s, 반환 없는 연산 v는 그 kcsan_mb 갈래에 들어가지 않아요. 기본형이라는 이유만으로 모든 함수에 같은 표식이 붙는 것은 아니에요.', '_acquire나 _relaxed이면 이 함수는 위의 두 표식을 출력하지 않아요. 특히 여기에는 kcsan_acquire를 출력하는 갈래가 없어요. 그래도 인자별 접근 hook을 만드는 반복은 진행해요.', '이 표식이 없다는 사실만으로 raw acquire의 실제 메모리 순서 약속이 없다고 결론 내리면 안 돼요. 분석용 코드의 생성 규칙과 raw 연산의 계약은 서로 다른 층이에요. 조건부 연산의 실제 실패 경로가 더 강한 CPU 순서를 얻었다고 판단하는 것도 피해야 해요.'], [('기본 반환 RMW의 접근 hook 앞에 이 생성기가 출력하는 분석 표식은 무엇인가요?', ['언제나 kcsan_release만 출력해요', '빈 순서 이름과 해당 meta 조건에서 kcsan_mb를 출력해요'], '정답은 두 번째예요. _release일 때의 갈래와 순서 이름이 비었을 때의 갈래는 달라요. 기본 fetch_add처럼 F인 경우 kcsan_mb가 접근 보고보다 먼저 나와요.'), ('이 함수는 _acquire를 만나면 앞에 kcsan_acquire를 출력하나요?', ['아니요. 이 함수에는 그 출력 갈래가 없어요', '네. 모든 순서 이름에 대응하는 표식을 반드시 하나씩 출력해요'], '정답은 첫 번째예요. 실제 조건문은 _release와 기본 full 분류를 처리해요. 다만 분석용 표식의 부재를 raw acquire의 계약 부재로 확대하면 안 돼요.')]), 'os1592': ('교체를 시도한다고 기록한 뒤 조건을 확인했더니 맞지 않아 물건을 그대로 둘 수 있어요. 시도 기록과 실제 교체 완료는 다른 사실이에요.', '조건 판정 전 접근 보고와 실제 저장 결과를 구별합니다.', '대상 5·예상 4·새 값 9에서 “보고 → raw 비교 → 실패 → 대상 5 유지, 예상 메모 5”를 그리세요.', ['생성된 wrapper는 checks라는 검사·보고 코드를 먼저 실행하고 그다음 raw 함수를 불러요. wrapper는 실제 연산을 감싸서 필요한 처리를 붙이는 함수예요. 순서를 읽으면 보고가 성공 판정 뒤에만 생기는 것이 아님을 알 수 있어요.', 'cmpxchg나 add_unless는 조건이 맞아야 대상을 바꿔요. 하지만 그 결과를 알기 전에 read_write 접근 보고가 이미 실행될 수 있어요. 보고 이름의 write를 보고 실제 저장이 반드시 끝났다고 판단하면 안 돼요.', 'try_cmpxchg에서 대상 5·예상 4·새 값 9라면 비교가 틀려 false를 반환해요. 대상 숫자는 5 그대로이고 예상 값을 담는 메모 old는 관찰한 5로 바뀌어요. 대상과 예상 메모 두 저장 공간을 따로 봐야 해요.', '기본 조건 연산 앞의 kcsan_mb도 raw 성공을 확인한 뒤 실행하는 if 안에 있지 않아요. 먼저 분석용 표식과 접근 보고를 하고 raw를 부르는 구조예요. 이것이 실패 때의 공개 API 순서 약속을 full로 바꾼다는 뜻은 아니에요.', '따라서 결과를 볼 때 보고 순서와 실제 저장값, 반환값을 함께 확인해야 해요. read_write 기록만 있으면 시도와 접근 분류는 알 수 있지만 조건이 맞아 counter가 바뀌었는지는 별도로 봐야 해요.', '연습에서는 위의 숫자로 한 번의 실패 흐름을 따라가요. 이 설명은 실제 KCSAN이 모든 경쟁을 찾아냈다는 뜻도, 실제 CPU의 실패 순서를 실험했다는 뜻도 아니에요. 소스의 보고 위치와 raw의 연산 계약을 연결하는 연습이에요.'], [('조건 비교가 실패하면 wrapper의 read_write 보고도 반드시 생략되나요?', ['네. 원문은 성공한 뒤에만 보고해요', '아니요. 보고 코드는 raw의 조건 판정보다 먼저 실행돼요'], '정답은 두 번째예요. checks → raw 호출의 순서를 보세요. 뒤에서 비교가 실패하더라도 앞에서 실행한 보고가 없어지는 것은 아니에요.'), ('read_write 보고가 남았다는 사실만으로 counter가 실제 바뀌었다고 알 수 있나요?', ['아니요. 조건 실패로 counter가 유지될 수 있어요', '네. 보고 종류가 실제 저장 결과까지 결정해요'], '정답은 첫 번째예요. 대상 5·예상 4인 비교 교체는 보고 후 실패해 대상 5를 유지할 수 있어요. 보고와 결과를 따로 확인해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_393.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
